"use client";

import React from "react";

import { Subscribe } from "@/registry/open-source/fancy-input";

export default function Usage() {
	return (
		<div className="h-screen w-full flex items-center justify-center relative overflow-hidden bg-black">
			<div className="p-4 w-full">
				<Subscribe />
			</div>
		</div>
	);
}

"use client";

import type React from "react";
import { useState } from "react";

import { cn } from "@/registry/utils/utils";
import { Loader } from "lucide-react";
import { AnimatePresence, motion } from "motion/react";

// Credit:
// https://starui.link/docs/components/subscribe

function Subscribe() {
	const [email, setEmail] = useState("");
	const [focus, setFocus] = useState(false);
	const [status, setStatus] = useState<"idle" | "loading" | "success">("idle");
	const label = "your@email.com";
	const letters = label.split("");

	const show = focus || email;

	const onSubmit = (event: React.FormEvent) => {
		event.preventDefault();
		setStatus("loading");

		setTimeout(() => {
			setStatus("success");
		}, 3000);
	};

	return (
		<form onSubmit={onSubmit} className="grow flex justify-center">
			<div className="relative max-w-96 w-full bg-white">
				<label
					htmlFor="email"
					className="absolute inset-0 flex items-center z-10 pointer-events-none"
				>
					<span className="flex">
						{letters.map((letter, index) => (
							<motion.span
								aria-hidden
								className={cn(
									"inline-block",
									show ? "text-amber-500" : "text-neutral-400"
								)}
								key={index + "fancy-input"}
								initial={false}
								animate={{
									x: 20,
									y: show ? -40 : 0,
									opacity: status === "success" ? 0 : 1,
								}}
								transition={{
									type: "spring",
									duration: 0.4,
									delay: index * 0.01,
								}}
							>
								{letter}
							</motion.span>
						))}
						<span className="sr-only">{label}</span>
					</span>
				</label>

				<div
					className={cn(
						"h-12 w-full transition-[border] border-2 flex items-center gap-2 rounded-full my-2 pl-5 relative overflow-hidden",
						show ? "border-amber-500" : "border-neutral-300"
					)}
				>
					<input
						id="email"
						name="email"
						type="email"
						title="email"
						className="border-none grow outline-none"
						placeholder=""
						required
						autoComplete="off"
						spellCheck="false"
						value={email}
						onChange={(e) => setEmail(e.target.value)}
						onFocus={() => setFocus(true)}
						onBlur={() => setFocus(false)}
					/>
					<motion.div
						className="absolute"
						initial={false}
						animate={{
							right: 4,
							x: show ? "calc(0% + 0px)" : "calc(100% + 4px)",
						}}
						transition={{ type: "spring", bounce: 0.3 }}
					>
						<motion.button
							layoutId="button"
							type="submit"
							style={{ borderRadius: 999 }}
							className="px-6 h-10 bg-gradient-to-b from-amber-400 to-amber-500 hover:from-amber-500 hover:to-amber-600 font-semibold flex-shrink-0 transition-colors text-white border-none"
						>
							Subscribe
						</motion.button>
					</motion.div>

					<AnimatePresence mode="popLayout">
						{status === "loading" && (
							<motion.div
								layoutId="button"
								className="absolute inset-0 z-10 bg-gradient-to-b from-amber-400 to-amber-500 flex items-center justify-center text-white"
								style={{ borderRadius: 999 }}
							>
								<Loader size={18} className="animate-spin" />
							</motion.div>
						)}

						{status === "success" && (
							<div className="absolute inset-0 z-10 bg-gradient-to-b from-amber-400 to-amber-500 flex items-center justify-center font-semibold text-white">
								<motion.span
									initial={{ y: -20, filter: "blur(4px)" }}
									animate={{ y: 0, filter: "blur(0px)" }}
									transition={{ type: "spring" }}
								>
									Your email has been subscribed!
								</motion.span>
							</div>
						)}
					</AnimatePresence>
				</div>
			</div>
		</form>
	);
}

export { Subscribe };

import registry from "@/registry.json";
import { clsx, type ClassValue } from "clsx";
import type { RegistryItem } from "shadcn/registry";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

const components = registry.items as unknown as RegistryItem[];

export const getComponents = (selectedTags: any[] = []): RegistryItem[] => {
	return selectedTags.length
		? components.filter((component) =>
				selectedTags.every(
					(tag) => component.meta?.tags?.includes(tag) ?? false
				)
			)
		: components;
};

export const getComponentsByNames = (names: string[]): RegistryItem[] => {
	const componentsMap = new Map(components.map((comp) => [comp.name, comp]));

	return names
		.map((name) => componentsMap.get(name))
		.filter((comp): comp is RegistryItem => comp !== undefined);
};

export const getAvailableTags = (selectedTags: any[]): any[] => {
	if (!selectedTags.length) return [];

	// Get all components that have all the selected tags
	const matchingComponents = components.filter((component) =>
		selectedTags.every((tag) => component.meta?.tags?.includes(tag) ?? false)
	);

	// Get all unique tags from the matching components
	const availableTags = new Set<any>();
	matchingComponents.forEach((component) => {
		component.meta?.tags?.forEach((tag: any) => {
			if (!selectedTags.includes(tag)) {
				availableTags.add(tag);
			}
		});
	});

	return Array.from(availableTags);
};

export const convertRegistryPaths = (content: string): string => {
	return content
		.replace(/@\/registry\/default\/ui/g, "@/components/ui")
		.replace(/@\/registry\/default\/compositions/g, "@/components")
		.replace(/@\/registry\/default\/hooks/g, "@/hooks")
		.replace(/@\/registry\/default\/lib/g, "@/lib");
};
